from pathlib import Path

ROOT = Path.cwd()
TARGET = ROOT / "backend" / "code_builder" / "ollama_service.py"
TEST = ROOT / "backend" / "tests" / "test_code_builder_ollama_event_loop.py"

text = TARGET.read_text(encoding="utf-8")

init_start = text.find("class OllamaService:")
if init_start < 0:
    raise SystemExit("OllamaService class not found")

old_init_start = text.find("        self._owns_client = client is None", init_start)
old_init_end_marker = "\n    async def __aenter__(self)"
old_init_end = text.find(old_init_end_marker, old_init_start)
if old_init_start < 0 or old_init_end < 0:
    raise SystemExit("OllamaService __init__ client block not found")

new_init = '''        # Production-owned HTTPX clients are request-scoped. Code Builder\n        # stages may execute through separate short-lived asyncio.run() loops;\n        # a reusable AsyncClient can therefore retain a transport bound to an\n        # event loop that has already closed. Injected clients remain supported\n        # for tests/integrations and are externally owned.\n        self._owns_client = client is None\n        self._closed = False\n        self._client = client\n'''
text = text[:old_init_start] + new_init + text[old_init_end:]

close_start = text.find("    async def close(self) -> None:", init_start)
sleep_marker = "    async def _sleep_before_retry("
close_end = text.find(sleep_marker, close_start)
if close_start < 0 or close_end < 0:
    raise SystemExit("close/_sleep boundaries not found")

new_close = '''    async def close(self) -> None:\n        """Close the service. Request-scoped owned clients close per request."""\n\n        if self._closed:\n            return\n\n        self._closed = True\n\n        # Injected clients are externally owned and intentionally not closed.\n\n    def _build_owned_client(self) -> httpx.AsyncClient:\n        """Create an HTTP client inside the currently running event loop."""\n\n        return httpx.AsyncClient(\n            base_url=self.configuration.base_url,\n            timeout=self.configuration.timeouts.to_httpx_timeout(),\n            verify=self.configuration.verify_tls,\n            follow_redirects=self.configuration.follow_redirects,\n            headers={\n                "Accept": "application/json",\n                "Content-Type": "application/json",\n                "User-Agent": self.configuration.user_agent,\n            },\n            limits=httpx.Limits(\n                max_connections=20,\n                max_keepalive_connections=10,\n                keepalive_expiry=30.0,\n            ),\n            trust_env=False,\n        )\n\n'''
text = text[:close_start] + new_close + text[close_end:]

req_start_marker = "    async def _request_json(\n"
req_end_marker = "    async def get_version(self) -> str:\n"
req_start = text.find(req_start_marker, init_start)
req_end = text.find(req_end_marker, req_start)
if req_start < 0 or req_end < 0:
    raise SystemExit("_request_json boundaries not found")

new_request = '''    async def _request_json(\n        self,\n        method: str,\n        endpoint: OllamaEndpoint,\n        *,\n        payload: Mapping[str, Any] | None = None,\n        timeout: httpx.Timeout | None = None,\n        retry: bool = True,\n    ) -> dict[str, Any]:\n        """Send an Ollama request and return a validated JSON object.\n\n        Owned clients are created and closed within the currently running\n        event loop, eliminating cross-loop HTTPX transport reuse.\n        """\n\n        self._ensure_open()\n        maximum_attempts = (\n            self.configuration.retries.maximum_retries + 1 if retry else 1\n        )\n        last_exception: BaseException | None = None\n        owned_client = self._build_owned_client() if self._owns_client else None\n        client = owned_client if owned_client is not None else self._client\n\n        if client is None:\n            raise OllamaServiceError("No Ollama HTTP client is available.")\n\n        try:\n            for attempt in range(maximum_attempts):\n                try:\n                    response = await client.request(\n                        method=method,\n                        url=endpoint.value,\n                        json=dict(payload) if payload is not None else None,\n                        timeout=timeout,\n                    )\n\n                    if (\n                        response.status_code in RETRYABLE_STATUS_CODES\n                        and attempt + 1 < maximum_attempts\n                    ):\n                        LOGGER.warning(\n                            "Transient Ollama HTTP status %s from %s; retrying request.",\n                            response.status_code,\n                            endpoint.value,\n                        )\n                        await self._sleep_before_retry(attempt)\n                        continue\n\n                    self._raise_for_ollama_status(response)\n                    return self._decode_json_response(response)\n\n                except asyncio.CancelledError as exc:\n                    raise OllamaRequestCancelledError(\n                        "The Ollama request was cancelled."\n                    ) from exc\n                except httpx.TimeoutException as exc:\n                    last_exception = exc\n                    if attempt + 1 < maximum_attempts:\n                        LOGGER.warning(\n                            "Ollama request to %s timed out; retrying.",\n                            endpoint.value,\n                        )\n                        await self._sleep_before_retry(attempt)\n                        continue\n                    raise OllamaTimeoutError(\n                        "Ollama did not respond before the configured timeout "\n                        f"for endpoint {endpoint.value}."\n                    ) from exc\n                except (\n                    httpx.ConnectError,\n                    httpx.NetworkError,\n                    httpx.RemoteProtocolError,\n                    httpx.LocalProtocolError,\n                ) as exc:\n                    last_exception = exc\n                    if attempt + 1 < maximum_attempts:\n                        LOGGER.warning(\n                            "Ollama connection failure for %s; retrying: %s",\n                            endpoint.value,\n                            exc,\n                        )\n                        await self._sleep_before_retry(attempt)\n                        continue\n                    raise OllamaUnavailableError(\n                        "Cannot connect to the local Ollama service at "\n                        f"{self.configuration.base_url}. Ensure Ollama is "\n                        "running and listening on the configured address."\n                    ) from exc\n                except httpx.RequestError as exc:\n                    last_exception = exc\n                    if attempt + 1 < maximum_attempts:\n                        LOGGER.warning(\n                            "Ollama transport error for %s; retrying: %s",\n                            endpoint.value,\n                            exc,\n                        )\n                        await self._sleep_before_retry(attempt)\n                        continue\n                    raise OllamaUnavailableError(\n                        f"Ollama request failed for {endpoint.value}: {exc}"\n                    ) from exc\n\n            raise OllamaUnavailableError(\n                "Ollama request failed after all retry attempts."\n            ) from last_exception\n        finally:\n            if owned_client is not None:\n                await owned_client.aclose()\n\n'''
text = text[:req_start] + new_request + text[req_end:]
TARGET.write_text(text, encoding="utf-8")

TEST.write_text('''import asyncio\nfrom unittest.mock import patch\n\nimport httpx\n\nfrom backend.code_builder.ollama_service import OllamaService\n\n\ndef test_owned_http_client_is_recreated_across_event_loops():\n    created = []\n\n    class FakeAsyncClient:\n        def __init__(self, *args, **kwargs):\n            self.loop = None\n            self.closed = False\n            created.append(self)\n\n        async def request(self, **kwargs):\n            loop = asyncio.get_running_loop()\n            if self.loop is None:\n                self.loop = loop\n            elif self.loop is not loop:\n                raise RuntimeError("Event loop is closed")\n            return httpx.Response(200, json={"version": "test"})\n\n        async def aclose(self):\n            self.closed = True\n\n    service = OllamaService()\n    with patch("backend.code_builder.ollama_service.httpx.AsyncClient", FakeAsyncClient):\n        assert asyncio.run(service.get_version()) == "test"\n        assert asyncio.run(service.get_version()) == "test"\n\n    assert len(created) == 2\n    assert all(client.closed for client in created)\n    assert created[0].loop is not created[1].loop\n''', encoding="utf-8")

print("FINAL_EVENT_LOOP_PATCH_V3_APPLIED")
